from rdkit import Chem
ss=['[C][C][=Branch1][C][=O][Cl]','[F][C][=C][C][=C][C][=C][Ring1][=Branch1]','[F][B][Branch1][C][F][F]']
for s in ss:
 m=Chem.MolFromSmiles(s,sanitize=False)
 print('\n',s)
 if m:
  for a in m.GetAtoms(): print(a.GetIdx(),a.GetSymbol(),[(n.GetIdx(),str(m.GetBondBetweenAtoms(a.GetIdx(),n.GetIdx()).GetBondType())) for n in a.GetNeighbors()])
